// The Root Rules Encyclopedia's data: the extracted Law of Root (generated by
// scripts/root/extract_law.py, never hand-edited) plus the editorial overlay in
// data/root/editorial/. Server-side only; pages pass what they need to client
// components as props.

import rulesData from "../../data/root/law-2025-10-13/rules.json" with { type: "json" };
import sectionsData from "../../data/root/law-2025-10-13/sections.json" with { type: "json" };
import factionsData from "../../data/root/law-2025-10-13/factions.json" with { type: "json" };
import sourceData from "../../data/root/law-2025-10-13/source.json" with { type: "json" };
import verificationData from "../../data/root/editorial/verification.json" with { type: "json" };
import { chapterHref, ruleHref } from "./paths.ts";

export type RuleType = "rule" | "sub-rule" | "glossary" | "section-text" | "chapter-text";

export type Rule = {
  id: string;
  rule_number: string | null;
  title: string | null;
  text: string;
  rule_type: RuleType;
  section_id: string;
  parent_rule_id: string | null;
  order: number;
  source_page_start: number;
  source_page_end: number;
  source_locations: { page: number; bbox: number[] }[];
  faction_ids: string[];
  faction_markers: string[];
  cross_references: { cited: string; target_id: string | null }[];
  source_version: string;
  layout_flags?: string[];
};

export type Section = {
  id: string;
  number: string | null;
  title: string;
  level: 1 | 2;
  parent_section_id: string | null;
  order: number;
  faction_id: string | null;
  expansion: string | null;
  source_page_start: number;
  rule_ids: string[];
};

export type Faction = {
  id: string;
  name: string;
  glyph: string;
  chapter_section_id: string;
  expansion: string | null;
  source_page_start: number;
};

export type Source = {
  source_version: string;
  title: string;
  printed_date: string;
  pdf_path: string;
  pdf_page_count: number;
  extractor_version: string;
  extracted_at: string;
  partial: boolean;
};

type Review = { id: string; date: string; method: string; reviewer: string; scope: string; result: string };

export type Verification =
  | { status: "verified"; review: Review }
  | { status: "unreviewed" };

const RULES = rulesData as unknown as Rule[];
const SECTIONS = sectionsData as unknown as Section[];
const FACTIONS = factionsData as unknown as Faction[];
export const SOURCE = sourceData as unknown as Source;
const VERIFICATION = verificationData as unknown as {
  reviews: Review[];
  rules: Record<string, { status: "verified"; review: string }>;
};

const RULES_BY_ID = new Map(RULES.map((rule) => [rule.id, rule]));
const SECTIONS_BY_ID = new Map(SECTIONS.map((section) => [section.id, section]));
const FACTIONS_BY_ID = new Map(FACTIONS.map((faction) => [faction.id, faction]));
const REVIEWS_BY_ID = new Map(VERIFICATION.reviews.map((review) => [review.id, review]));

// Book order everywhere.
const CHAPTERS = SECTIONS.filter((s) => s.level === 1).sort((a, b) => a.order - b.order);

const RULES_BY_SECTION = new Map<string, Rule[]>();
const CHILDREN = new Map<string, Rule[]>();
const CITED_BY = new Map<string, Rule[]>();
for (const rule of [...RULES].sort((a, b) => a.order - b.order)) {
  RULES_BY_SECTION.set(rule.section_id, [...(RULES_BY_SECTION.get(rule.section_id) ?? []), rule]);
  if (rule.parent_rule_id) CHILDREN.set(rule.parent_rule_id, [...(CHILDREN.get(rule.parent_rule_id) ?? []), rule]);
  for (const ref of new Set(rule.cross_references.map((r) => r.target_id))) {
    if (ref) CITED_BY.set(ref, [...(CITED_BY.get(ref) ?? []), rule]);
  }
}

export function allRules(): Rule[] {
  return RULES;
}

export function getRule(id: string): Rule | undefined {
  return RULES_BY_ID.get(id);
}

export function getSection(id: string): Section | undefined {
  return SECTIONS_BY_ID.get(id);
}

export function chapters(): Section[] {
  return CHAPTERS;
}

// A level-2 section's chapter, or the chapter itself.
export function chapterOf(sectionId: string): Section {
  const section = SECTIONS_BY_ID.get(sectionId);
  if (!section) throw new Error(`Unknown section ${sectionId}`);
  return section.level === 1 ? section : chapterOf(section.parent_section_id!);
}

export function sectionsOf(chapterId: string): Section[] {
  return SECTIONS.filter((s) => s.parent_section_id === chapterId).sort((a, b) => a.order - b.order);
}

// Records filed directly under a section (for a chapter: its introduction).
export function rulesIn(sectionId: string): Rule[] {
  return RULES_BY_SECTION.get(sectionId) ?? [];
}

// Every record in a chapter, in book order.
export function rulesInChapter(chapterId: string): Rule[] {
  return RULES.filter((rule) => chapterOf(rule.section_id).id === chapterId);
}

export function pageRange(rules: Rule[]): { start: number; end: number } {
  return {
    start: Math.min(...rules.map((r) => r.source_page_start)),
    end: Math.max(...rules.map((r) => r.source_page_end)),
  };
}

export function childrenOf(ruleId: string): Rule[] {
  return CHILDREN.get(ruleId) ?? [];
}

// Parent, grandparent… nearest last.
export function ancestorsOf(rule: Rule): Rule[] {
  const chain: Rule[] = [];
  let parent = rule.parent_rule_id ? RULES_BY_ID.get(rule.parent_rule_id) : undefined;
  while (parent) {
    chain.unshift(parent);
    parent = parent.parent_rule_id ? RULES_BY_ID.get(parent.parent_rule_id) : undefined;
  }
  return chain;
}

// Records whose text cites this rule or section.
export function citedBy(targetId: string): Rule[] {
  return CITED_BY.get(targetId) ?? [];
}

// The records before and after this one in book order.
export function neighbours(rule: Rule): { previous?: Rule; next?: Rule } {
  const index = RULES.findIndex((r) => r.id === rule.id);
  return { previous: RULES[index - 1], next: RULES[index + 1] };
}

export function factions(): Faction[] {
  return FACTIONS;
}

export function getFaction(id: string): Faction | undefined {
  return FACTIONS_BY_ID.get(id);
}

export type ChapterGroup = "core" | "faction" | "appendix";

export function chapterGroup(chapter: Section): ChapterGroup {
  if (chapter.faction_id) return "faction";
  return chapter.number && /^[A-Z]$/.test(chapter.number) ? "appendix" : "core";
}

// "6. Marquise de Cat", "Appendix G: Glossary", "Reading the Law".
export function chapterLabel(chapter: Section): string {
  if (!chapter.number) return chapter.title;
  return chapterGroup(chapter) === "appendix"
    ? `Appendix ${chapter.number}: ${chapter.title}`
    : `${chapter.number}. ${chapter.title}`;
}

// A cross-reference target's page: rules have their own; sections are anchors
// in their chapter.
export function targetHref(targetId: string): string {
  if (targetId.startsWith("rule-")) return ruleHref(targetId);
  const chapter = chapterOf(targetId);
  return chapterHref(chapter.id, chapter.id === targetId ? undefined : targetId);
}

export function targetLabel(targetId: string): string {
  const rule = RULES_BY_ID.get(targetId);
  if (rule) return ruleLabel(rule);
  const section = SECTIONS_BY_ID.get(targetId);
  if (!section) return targetId;
  return section.level === 1 ? chapterLabel(section) : `${section.number} ${section.title}`;
}

// "6.2.3 Field Hospitals"; unnumbered records fall back to their section.
export function ruleLabel(rule: Rule): string {
  const title = rule.title ? plainTitle(rule.title) : "";
  if (rule.rule_number) return title ? `${rule.rule_number} ${title}` : rule.rule_number;
  if (rule.rule_type === "chapter-text") return `${chapterLabel(chapterOf(rule.section_id))} (introduction)`;
  return title || rule.id;
}

function plainTitle(title: string): string {
  // An unreadable inline icon (H.2.1–H.2.4) stays visible as "icon" rather than "()".
  return title.replace(/\{item:([a-z]+)\}/g, "$1").replace(/\{icon\}/g, "icon").replace(/\*/g, "").replace(/\s{2,}/g, " ").trim();
}

export function verificationOf(ruleId: string): Verification {
  const entry = VERIFICATION.rules[ruleId];
  const review = entry && REVIEWS_BY_ID.get(entry.review);
  return review ? { status: "verified", review } : { status: "unreviewed" };
}
